import './style.css';
import './mobile.css';
import { PRESETS } from '../data/presets';
import { loadSpeciesDatabase } from '../data/species-database';
import { createPetalPatternMap } from '../flower/petal-pattern';
import type { PetalPatternProfile } from '../flower/petal-pattern';
import type { BloomRenderer, RendererFrameInfo } from '../render/bloom-renderer';
import { createRecipe, parseLibrary, parseRecipe, inspectRecipe, applyEvidence, generateVariants, type Recipe, type Evidence } from './recipe';
import { bakeSnapshot, inspectMesh, disposeSnapshot, exportSpecimen, downloadBlob, downloadJSON, safeName } from './assets';
import { STUDIO_RENDER, fieldSettings } from './settings';

const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id)! as T;
const input = (id: string) => $<HTMLInputElement>(id);
const select = (id: string) => $<HTMLSelectElement>(id);
const escapeHTML = (v: unknown) => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const STORE='floraxis.studio.library.v1';
const saved = new Set<string>();
let recipes = PRESETS.map(p => {const r=createRecipe(p.id);r.id=`template-${p.id}`;return r;});
let current = recipes.find(r=>r.templateId==='hydrangea')!;
let activeFilter='all', renderer: BloomRenderer|undefined, ready=false, playing=false, bloom=1, field=false;
let previewTimer=0, buildTimer=0, storeTimer=0, lastFrame=0, dirtyModel=false;
let storageProblem='';
try {
  const raw=localStorage.getItem(STORE);
  if(raw){
    const envelope=JSON.parse(raw);
    const imported=parseLibrary(envelope);
    imported.forEach(r=>{const index=recipes.findIndex(p=>p.id===r.id);if(index<0)recipes.push(r);else recipes[index]=r;saved.add(r.id);});
    current=recipes.find(r=>r.id===envelope.activeId)??current;
  }
} catch {storageProblem='이전 저장 데이터를 읽지 못했습니다. 자동 덮어쓰기를 중지했습니다. JSON을 먼저 백업하세요.';}

function toast(message: string) {$('toast').textContent=message;$('toast').classList.add('visible');window.setTimeout(()=>$('toast').classList.remove('visible'),5000);}
function persist() {
  if(storageProblem){$('save-state').textContent=storageProblem;return;}
  try {
    localStorage.setItem(STORE,JSON.stringify({schema:'floraxis.library',version:1,activeId:current.id,recipes:recipes.filter(r=>saved.has(r.id))}));
    $('save-state').textContent='이 브라우저에 저장됨';
  } catch {$('save-state').textContent='저장 공간 부족 · JSON 백업 필요';toast('브라우저 저장에 실패했습니다. 라이브러리를 JSON으로 내보내세요.');}
}
function touch(rebuild=true) {
  current.updatedAt=new Date().toISOString();current.revision++;saved.add(current.id);
  current.preset.name=current.title;current.preset.scientificName=current.scientificName;
  current.preset.pattern!.seed=current.seed;
  const index=recipes.findIndex(r=>r.id===current.id);if(index<0)recipes.push(current);else recipes[index]=current;
  $('save-state').textContent='저장 중…';window.clearTimeout(storeTimer);storeTimer=window.setTimeout(persist,400);
  updateHeader();renderLibrary();renderReview();
  if(rebuild){dirtyModel=true;window.clearTimeout(previewTimer);previewTimer=window.setTimeout(renderPreview,240);invalidateMesh();}
}
function updateHeader(){
  $('specimen-title').textContent=current.title;$('specimen-scientific').textContent=current.scientificName||'학명 확인 전 · '+current.templateId;
  const review=inspectRecipe(current);$('recipe-status').textContent=review.status==='draft'?'절차적 초안':'근거 연결됨';
  $('recipe-status').classList.toggle('linked',review.status!=='draft');
}
function invalidateMesh(){ $('mesh-state').textContent='변경됨 · 재검사 필요';$('mesh-report').textContent='현재 개화 단계의 단일 꽃을 검사하고 내보냅니다. GLB에는 레시피·출처가 포함되며 GPU 패턴은 텍스처로 변환됩니다.'; }
function renderLibrary(){
  const q=input('search').value.toLowerCase();
  const filtered=recipes.filter(r=>(activeFilter!=='saved'||saved.has(r.id))&&(activeFilter!=='hydrangea'||r.preset.kind==='hydrangea')&&`${r.title} ${r.scientificName}`.toLowerCase().includes(q));
  $('library-count').textContent=`${recipes.length} RECIPES`;
  $('recipe-list').innerHTML=filtered.length?filtered.map(r=>`<button class="recipe-card ${r.id===current.id?'active':''}" data-recipe="${escapeHTML(r.id)}" aria-pressed="${r.id===current.id}"><span class="specimen-icon" style="--petal:${/^#[0-9a-f]{6}$/i.test(r.preset.colors.tip)?r.preset.colors.tip:'#c997ad'}">✿</span><span><strong>${escapeHTML(r.title)}</strong><small>${escapeHTML(r.scientificName||'분류명 미확인')}</small><em>${saved.has(r.id)?'내 레시피':'시작 템플릿'} · ${r.evidence.length} 관찰값</em></span></button>`).join(''):'<p class="empty">검색 결과가 없습니다.</p>';
}

const morphFields = [
  ['petalCount','꽃잎·장식 소화 수',3,96,1],['layers','꽃잎 층',1,6,1],['petalLength','꽃잎 길이 비율',0.45,2.4,0.01],['petalWidth','꽃잎 너비 비율',0.16,1.4,0.01],
  ['openAngle','개방각 °',18,142,1],['cup','컵 곡률',-0.2,0.8,0.01],['curl','끝단 말림',-0.35,1.2,0.01],['waviness','가장자리 물결',0,0.3,0.005],
] as const;
const patternFields=[['strength','무늬 강도',0,1,0.01],['veinFrequency','맥상 빈도',1,20,1],['spotDensity','반점 밀도',0,1,0.01],['edgeStrength','가장자리 색소',0,1,0.01]] as const;
function sliders(target: string, fields: ReadonlyArray<readonly [string,string,number,number,number]>, prefix: string){
  $(target).innerHTML=fields.map(([key,label,min,max,step])=>`<label class="range-field" for="${prefix}-${key}"><span>${label}</span><output id="${prefix}-${key}-value"></output><input id="${prefix}-${key}" data-${prefix}="${key}" type="range" min="${min}" max="${max}" step="${step}" /></label>`).join('');
}
sliders('morph-controls',morphFields,'morph');sliders('pattern-controls',patternFields,'pattern');
function drawPattern(){
  const canvas=$<HTMLCanvasElement>('pattern-canvas');
  const texture=createPetalPatternMap(current.preset.pattern!,canvas.width,canvas.height);
  const data=new Uint8ClampedArray(texture.image.data!);
  // DataTexture is linear; PNG/canvas is sRGB.
  for(let i=0;i<data.length;i+=4)for(let c=0;c<3;c++){const n=data[i+c]/255;data[i+c]=Math.round((n<=0.0031308?12.92*n:1.055*n**(1/2.4)-0.055)*255);}
  canvas.getContext('2d')!.putImageData(new ImageData(data,canvas.width,canvas.height),0,0);texture.dispose();
}
function renderReview(){
  const review=inspectRecipe(current);
  $('review-issues').innerHTML=review.issues.length?review.issues.map(s=>`<li>${escapeHTML(s)}</li>`).join(''):'<li>출처·관찰값·분류명 연결이 완료됐습니다. 원자료와 형태의 일치 여부를 최종 검수하세요.</li>';
  const t=current.taxonomy;
  $('taxonomy-result').textContent=t&&current.taxonomyName===current.scientificName?`${t.acceptedName||t.canonicalName} · ${t.rank} · 매칭 ${t.confidence}% (형태 검증과 별개)`:'현재 학명의 분류 메타데이터를 확인하세요.';
}
function renderEvidence(){
  $('source-count').textContent=`${current.sources.length} SOURCES`;
  $('sources').innerHTML=current.sources.map(s=>`<article class="source-card"><a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.label)} ↗</a><small>${escapeHTML(s.license||'이용 조건 확인 필요')}</small></article>`).join('')||'<p class="hint">출처를 연결해 연구를 시작하세요.</p>';
  const labels={petalLength:'꽃잎 길이',petalWidth:'꽃잎 너비',flowerDiameter:'꽃 지름',plantHeight:'식물 높이'};
  $('evidence-list').innerHTML=current.evidence.map(e=>`<article class="source-card"><b>${labels[e.trait]} · ${e.value} ± ${e.uncertainty} ${e.unit}</b><small>${e.origin==='procedural'?'절차적 가정':e.origin==='measured'?'직접 실측':'문헌 관찰'} · ${escapeHTML(e.locator||'출처 위치 미입력')} · ${escapeHTML(e.reviewer||'검수 전')}</small></article>`).join('');
  renderReview();
}
function syncControls(){
  updateHeader();renderLibrary();renderEvidence();
  input('recipe-title').value=current.title;input('scientific-name').value=current.scientificName;input('family').value=current.family;input('batch-seed').value=String(current.seed);
  for(const [key] of morphFields){input(`morph-${key}`).value=String(current.preset.morphology[key]);$(`morph-${key}-value`).textContent=String(current.preset.morphology[key]);}
  for(const [key] of patternFields){input(`pattern-${key}`).value=String(current.preset.pattern![key]);$(`pattern-${key}-value`).textContent=String(current.preset.pattern![key]);}
  input('base-color').value=current.preset.colors.base;input('tip-color').value=current.preset.colors.tip;input('pattern-color').value=current.preset.pattern!.color;select('pattern-mode').value=current.preset.pattern!.mode;
  drawPattern();
}
function renderPreview(){
  if(!ready||!renderer)return;
  window.clearTimeout(buildTimer);
  $('renderer-loading').hidden=false;$('renderer-loading').textContent='형태 생성 중…';
  // Leave input handlers promptly, and let the loading state paint before large fields build.
  buildTimer=window.setTimeout(buildPreview,32);
}
function buildPreview(){
  if(!renderer)return;
  try {
    if(field)renderer.setField(fieldSettings(current.preset.id,Number(select('field-count').value),current.seed),[current.preset]);
    else renderer.setFlower(current.preset);
    renderer.setBloom(bloom);dirtyModel=false;$('renderer-loading').hidden=true;
  } catch(error){toast(`생성 오류: ${String(error)}`);$('renderer-loading').hidden=false;$('renderer-loading').textContent='형태 생성 실패 · 파라미터를 확인하세요.';}
}
function selectRecipe(id: string){const next=recipes.find(r=>r.id===id);if(!next)return;persist();current=next;playing=false;input('bloom').value='100';bloom=1;$('bloom-value').textContent='100%';updatePlay();syncControls();renderPreview();persist();invalidateMesh();}
function setTab(name: string){document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===name)));for(const tab of ['shape','evidence','batch'])$(`panel-${tab}`).hidden=tab!==name;}
function updatePlay(){$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'개화 일시 정지':'개화 재생');}
function frame(delta: number, elapsed: number, info: RendererFrameInfo){
  if(playing){bloom+=delta*0.08;if(bloom>1)bloom=0;renderer?.setBloom(bloom);input('bloom').value=String(Math.round(bloom*100));$('bloom-value').textContent=`${Math.round(bloom*100)}%`;}
  if(elapsed-lastFrame<500)return;lastFrame=elapsed;
  $('frame-info').textContent=`${info.fps} FPS · ${info.drawCalls} draws · ${info.triangles.toLocaleString()} triangles`;
  const lod=info.fieldOptimization;
  $('lod-info').textContent=field?`자동 LOD · ${info.qualityTier} · 꽃차례 ${lod?lod.hero+lod.near+lod.mid+lod.far:0} 표시 / ${lod?.culled??0} 제외 · 해상도 ${Math.round(info.resolutionScale*100)}%`:'단일 꽃 · 전체 형태';
}
const run = async (button: HTMLElement, action:()=>Promise<void>)=>{(button as HTMLButtonElement).disabled=true;try{await action();}catch(error){if(button.id==='export-glb')$('mesh-state').textContent='내보내기 실패 · 다시 시도';toast(error instanceof Error?error.message:String(error));}finally{(button as HTMLButtonElement).disabled=false;}};
async function fetchJSON(url: string){const response=await fetch(url,{signal:AbortSignal.timeout(18000),headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`자료 수집 실패 (${response.status}). 기존 자료는 보존됩니다.`);return response.json();}

$('recipe-list').addEventListener('click',e=>{const card=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-recipe]');if(card)selectRecipe(card.dataset.recipe!);});
input('search').addEventListener('input',renderLibrary);
document.querySelectorAll<HTMLButtonElement>('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter!;document.querySelectorAll('[data-filter]').forEach(el=>el.classList.toggle('selected',el===b));renderLibrary();}));
document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab!)));
for(const [key] of morphFields)input(`morph-${key}`).addEventListener('input',e=>{current.preset.morphology[key]=Number((e.target as HTMLInputElement).value);$(`morph-${key}-value`).textContent=String(current.preset.morphology[key]);touch();});
for(const [key] of patternFields)input(`pattern-${key}`).addEventListener('input',e=>{current.preset.pattern![key]=Number((e.target as HTMLInputElement).value);$(`pattern-${key}-value`).textContent=String(current.preset.pattern![key]);drawPattern();touch();});
select('pattern-mode').addEventListener('change',()=>{current.preset.pattern!.mode=select('pattern-mode').value as PetalPatternProfile['mode'];drawPattern();touch();});
for(const [id,update] of [['base-color',(v:string)=>current.preset.colors.base=v],['tip-color',(v:string)=>current.preset.colors.tip=v],['pattern-color',(v:string)=>current.preset.pattern!.color=v]] as const)input(id).addEventListener('input',()=>{update(input(id).value);drawPattern();touch();});
for(const [id,key] of [['recipe-title','title'],['scientific-name','scientificName'],['family','family']] as const)input(id).addEventListener('input',()=>{current[key]=input(id).value;touch(false);});
$('duplicate').addEventListener('click',()=>{current=structuredClone(current);current.id=crypto.randomUUID();current.title+=' · 사본';current.revision=0;touch(false);syncControls();toast('독립된 사본을 라이브러리에 저장했습니다.');});
$('view-single').addEventListener('click',()=>setView(false));$('view-field').addEventListener('click',()=>setView(true));
function setView(value:boolean){field=value;$('view-single').classList.toggle('selected',!field);$('view-field').classList.toggle('selected',field);$('field-count-label').hidden=!field;renderPreview();}
select('field-count').addEventListener('change',()=>{renderPreview();window.setTimeout(()=>renderer?.focusScene(),40);});$('reset-camera').addEventListener('click',()=>renderer?.focusScene());
input('bloom').addEventListener('input',()=>{playing=false;updatePlay();bloom=Number(input('bloom').value)/100;$('bloom-value').textContent=`${Math.round(bloom*100)}%`;renderer?.setBloom(bloom);$('mesh-state').textContent='개화 단계 변경 · 재검사 필요';});
$('play').addEventListener('click',()=>{playing=!playing;if(playing&&bloom===1)bloom=0;updatePlay();});
$('capture').addEventListener('click',()=>{if(!ready)return toast('3D 화면이 준비된 후 캡처하세요.');renderer?.capture();});
$('export-recipe').addEventListener('click',()=>downloadJSON(current,`${safeName(current.title)}.recipe.json`));
$('export-library').addEventListener('click',()=>downloadJSON({schema:'floraxis.library',version:1,exportedAt:new Date().toISOString(),activeId:current.id,recipes},'floraxis-library.json'));
$('import-library').addEventListener('click',()=>input('import-file').click());
$('import-text').addEventListener('click',()=>{$<HTMLTextAreaElement>('json-text').value=JSON.stringify(current,null,2);$<HTMLDialogElement>('json-dialog').showModal();});
$('json-cancel').addEventListener('click',()=>$<HTMLDialogElement>('json-dialog').close());
$('json-form').addEventListener('submit',event=>{event.preventDefault();try{
  const raw=$<HTMLTextAreaElement>('json-text').value;if(raw.length>10_000_000)throw new Error('JSON은 10 MB 이하로 입력하세요.');
  const imported=parseLibrary(JSON.parse(raw));if(recipes.length+imported.length>200)throw new Error('라이브러리 한도 200개를 초과합니다.');
  for(const r of imported){r.id=crypto.randomUUID();recipes.push(r);saved.add(r.id);}if(imported.length)current=imported[0];persist();syncControls();renderPreview();invalidateMesh();$<HTMLDialogElement>('json-dialog').close();toast(`${imported.length}개 레시피를 새 사본으로 가져왔습니다.`);
}catch(error){toast(error instanceof Error?error.message:String(error));}});
input('import-file').addEventListener('change',e=>{void run($('import-library'),async()=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>10_000_000)throw new Error('JSON 파일은 10 MB 이하로 가져오세요.');const imported=parseLibrary(JSON.parse(await file.text()));
  // Imports are added as new copies so an existing recipe can always be recovered.
  if(recipes.length+imported.length>200)throw new Error('라이브러리 한도 200개를 초과합니다. 더 작은 묶음으로 가져오세요.');
  for(const r of imported){r.id=crypto.randomUUID();recipes.push(r);saved.add(r.id);}if(imported.length)current=imported[0];persist();syncControls();renderPreview();toast(`${imported.length}개 레시피를 새 사본으로 가져왔습니다.`);input('import-file').value='';});});
$('export-pattern').addEventListener('click',()=>{$<HTMLCanvasElement>('pattern-canvas').toBlob(blob=>{if(blob)downloadBlob(blob,`${safeName(current.title)}-pattern.png`);});});
$('export-glb').addEventListener('click',()=>void run($('export-glb'),async()=>{playing=false;updatePlay();if(dirtyModel)renderPreview();$('mesh-state').textContent='GLB 생성 중…';const result=await exportSpecimen(parseRecipe(current),bloom);showMeshReport(result.report);toast('현재 형태의 GLB를 내보냈습니다. 레시피와 출처가 파일에 포함됩니다.');}));
function showMeshReport(report: ReturnType<typeof inspectMesh>){$('mesh-state').textContent=report.invalidValues?'검사 실패':'기하 검사 완료';$('mesh-report').textContent=`${report.meshes}개 메시 · ${report.vertices.toLocaleString()} 정점 · ${report.triangles.toLocaleString()} 삼각형 · 비정상 좌표 ${report.invalidValues} · 영면적 삼각형 ${report.degenerateTriangles}. 정규화 단위 / PBR 재질 / 현재 개화 단계. 기하 검사는 생물학적 검증과 별개입니다.`;}
$('inspect-mesh').addEventListener('click',()=>void run($('inspect-mesh'),async()=>{const {FloweringPlantModel}=await import('../flower/flowering-plant-model');const model=new FloweringPlantModel(parseRecipe(current).preset);try{model.update(bloom,0);const snapshot=bakeSnapshot(model.root);try{showMeshReport(inspectMesh(snapshot));}finally{disposeSnapshot(snapshot);}}finally{model.dispose();}}));

$('match-taxonomy').addEventListener('click',()=>void run($('match-taxonomy'),async()=>{const targetId=current.id,name=current.scientificName.trim();if(!name)throw new Error('학명을 입력하세요.');const payload=await fetchJSON(`https://api.gbif.org/v2/species/match?${new URLSearchParams({scientificName:name,checklistKey:'7ddf754f-d193-4cc9-b351-99906754a03b'})}`);if(!payload.usage)throw new Error('분류명 매칭 결과가 없습니다. 학명과 동의어를 확인하세요.');
  const target=recipes.find(r=>r.id===targetId);if(!target||target.scientificName.trim()!==name)throw new Error('학명이 바뀌었습니다. 현재 학명으로 다시 확인하세요.');
  target.taxonomy={key:payload.usage.key??null,acceptedName:payload.usage.name??null,canonicalName:payload.usage.canonicalName??null,rank:payload.usage.rank??null,status:payload.usage.status??null,matchType:payload.diagnostics?.matchType??null,confidence:Number(payload.diagnostics?.confidence??0),classification:(payload.classification??[]).map((v:{key:string;name:string;rank:string})=>({key:v.key,name:v.name,rank:v.rank}))};target.taxonomyName=name;saved.add(target.id);persist();if(current.id===targetId){touch(false);renderReview();}toast('GBIF 분류 메타데이터를 연결했습니다.');}));
$('source-form').addEventListener('submit',e=>{e.preventDefault();void run($('source-form').querySelector('button')!,async()=>{
  const targetId=current.id,raw=input('source-url').value.trim(),doi=raw.replace(/^https?:\/\/(dx\.)?doi.org\//,'');
  let source: Recipe['sources'][number];
  if(/^10\.\d{4,9}\//.test(doi)){const payload=await fetchJSON(`https://api.crossref.org/works/${encodeURIComponent(doi)}`);const m=payload.message;if(!m?.DOI)throw new Error('DOI 메타데이터를 찾지 못했습니다.');source={label:m.title?.[0]||doi,url:`https://doi.org/${m.DOI}`,doi:m.DOI,license:(m.license??[]).map((l:{URL:string})=>l.URL).filter(Boolean).join(' · ')||'논문 이용 조건 별도 확인 · 서지 메타데이터만 저장'};}
  else {const url=new URL(raw);if(url.protocol!=='https:')throw new Error('HTTPS URL 또는 DOI를 입력하세요.');source={label:url.hostname+url.pathname.slice(0,60),url:url.href,license:'링크만 연결 · 원자료 이용 조건 확인 필요'};}
  const target=recipes.find(r=>r.id===targetId);if(!target)return;if(target.sources.some(s=>s.url===source.url))throw new Error('이미 연결된 출처입니다.');target.sources.push(source);saved.add(targetId);persist();if(current.id===targetId){input('source-url').value='';touch(false);renderEvidence();}toast('출처를 레시피에 연결했습니다.');});});
