import { PRESETS } from '../data/presets';
import { GENERATED_SPECIES_PATTERNS } from '../data/generated-species-patterns';
import type { SpeciesDatabaseRecord } from '../data/species-database';
import type { FlowerPreset } from '../types';
import { sanitizePreset, seededRandom } from '../utils';

export const RECIPE_VERSION = 1;
export interface Evidence {
  id: string;
  trait: 'petalLength' | 'petalWidth' | 'flowerDiameter' | 'plantHeight';
  value: number;
  unit: 'mm' | 'cm';
  origin: 'measured' | 'reference' | 'procedural';
  sourceUrl: string;
  locator: string;
  uncertainty: number;
  reviewer: string;
  license: string;
}
export interface Recipe {
  schema: 'floraxis.recipe';
  version: 1;
  id: string;
  templateId: string;
  title: string;
  scientificName: string;
  family: string;
  seed: number;
  revision: number;
  updatedAt: string;
  preset: FlowerPreset;
  evidence: Evidence[];
  sources: Array<{ label: string; url: string; license: string; doi?: string }>;
  taxonomy: SpeciesDatabaseRecord['taxonomy'];
  taxonomyName: string;
  note: string;
}
export const createRecipe = (templateId: string, record?: SpeciesDatabaseRecord): Recipe => {
  const preset = sanitizePreset(structuredClone(PRESETS.find(p => p.id === templateId) ?? PRESETS[0]));
  preset.pattern = { ...GENERATED_SPECIES_PATTERNS[preset.id], procedural: true };
  return {
    schema: 'floraxis.recipe', version: 1, id: crypto.randomUUID(), templateId: preset.id,
    title: preset.name, scientificName: record?.scientificName ?? preset.scientificName.split(' · ')[0], family: record?.family ?? preset.family,
    seed: preset.pattern.seed, revision: 1, updatedAt: new Date().toISOString(), preset,
    evidence: [], sources: (record?.references ?? preset.sources).map(source => ({
      label: source.label, url: source.url, license: '이용 조건 확인 필요',
      ...('doi' in source && typeof source.doi === 'string' ? { doi: source.doi } : {}),
    })), taxonomy: record?.taxonomy ?? null, taxonomyName: record?.scientificName ?? '',
    note: '문헌을 참고해 조정한 절차적 제작 초안. 메타데이터 매칭은 형태의 실측 검증을 의미하지 않습니다.',
  };
};

export function inspectRecipe(recipe: Recipe) {
  const issues: string[] = [];
  if (!recipe.scientificName.trim()) issues.push('학명을 입력하세요.');
  if (!recipe.sources.length) issues.push('근거 출처를 추가하세요.');
  const matched = recipe.taxonomyName === recipe.scientificName && recipe.taxonomy
    && ['SPECIES', 'SUBSPECIES', 'VARIETY', 'FORM'].includes(recipe.taxonomy.rank ?? '')
    && recipe.taxonomy.confidence >= 80;
  if (!matched) issues.push('종 수준의 분류명 확인이 필요합니다.');
  const observed = recipe.evidence.filter(e => e.origin !== 'procedural');
  if (!observed.length) issues.push('형태는 절차적 초안입니다. 단위가 있는 관찰값을 연결하세요.');
  if (observed.some(e => !e.sourceUrl || !e.locator || !e.reviewer || !e.license || e.license === '확인 필요')) {
    issues.push('관찰값의 출처 위치·검수자·이용 조건을 완성하세요.');
  }
  return { status: issues.length ? 'draft' : 'evidence-linked', issues, observed: observed.length, matched: Boolean(matched) };
}

export function applyEvidence(recipe: Recipe, evidence: Evidence): Recipe {
  if (!Number.isFinite(evidence.value) || evidence.value <= 0 || evidence.value > 100000
    || !Number.isFinite(evidence.uncertainty) || evidence.uncertainty < 0) throw new Error('측정값과 오차 범위를 확인하세요.');
  if (evidence.origin !== 'procedural' && !/^https:\/\//.test(evidence.sourceUrl)) throw new Error('실측·문헌값에는 HTTPS 출처가 필요합니다.');
  const next = structuredClone(recipe);
  const cm = evidence.value * (evidence.unit === 'mm' ? 0.1 : 1);
  const base = PRESETS.find(p => p.id === next.templateId)!;
  // Map physical dimensions relative to the chosen template; the display mesh remains normalized.
  if (evidence.trait === 'flowerDiameter' && next.preset.architecture) {
    next.preset.architecture.defaultFlowerDiameterCm = cm;
    next.preset.morphology.flowerScale = base.morphology.flowerScale * cm / base.architecture!.defaultFlowerDiameterCm;
  } else if (evidence.trait === 'plantHeight' && next.preset.architecture) {
    next.preset.architecture.defaultHeightCm = cm;
    next.preset.morphology.stemHeight = base.morphology.stemHeight * cm / base.architecture!.defaultHeightCm;
  }
  next.evidence.push(structuredClone(evidence));
  const length = [...next.evidence].reverse().find(e => e.trait === 'petalLength');
  const width = [...next.evidence].reverse().find(e => e.trait === 'petalWidth');
  if (length && width) {
    const ratio = width.value * (width.unit === 'mm' ? 0.1 : 1) / (length.value * (length.unit === 'mm' ? 0.1 : 1));
    next.preset.morphology.petalWidth = next.preset.morphology.petalLength * ratio;
  }
  next.preset.morphology.flowerScale = Math.max(0.15, Math.min(4, next.preset.morphology.flowerScale));
  next.preset.morphology.stemHeight = Math.max(0.3, Math.min(6, next.preset.morphology.stemHeight));
  next.preset = sanitizePreset(next.preset);
  return next;
}

export function generateVariants(recipe: Recipe, count: number, amount: number): Recipe[] {
  if (!Number.isInteger(count) || count < 1 || count > 24) throw new Error('변이는 1~24개 생성할 수 있습니다.');
  const random = seededRandom(recipe.seed);
  const spread = Math.max(0, Math.min(0.35, amount));
  return Array.from({ length: count }, (_, index) => {
    const next = structuredClone(recipe);
    next.id = `${recipe.id}-r${recipe.revision}-s${recipe.seed}-v${index + 1}`;
    next.title = `${recipe.title} · 변이 ${String(index + 1).padStart(2, '0')}`;
    next.revision = 1;
    next.note = `시드 ${recipe.seed}, 편차 ${Math.round(spread * 100)}%로 생성한 절차적 변이. 원본: ${recipe.title}`;
    for (const key of ['petalLength', 'petalWidth', 'cup', 'curl', 'waviness'] as const) {
      next.preset.morphology[key] *= 1 + (random() * 2 - 1) * spread;
    }
    next.seed = Math.floor(random() * 1000000);
    next.preset.pattern!.seed = next.seed;
    // Reference observations remain attached as references, not measurements of this synthetic variant.
    next.evidence = next.evidence.map(e => ({ ...e, origin: 'procedural' }));
    next.preset = sanitizePreset(next.preset);
    return next;
  });
}

export function parseRecipe(value: unknown): Recipe {
  if (!value || typeof value !== 'object') throw new Error('레시피 객체가 필요합니다.');
  const r = value as Recipe;
  const base = PRESETS.find(p => p.id === r.templateId);
  if (r.schema !== 'floraxis.recipe' || r.version !== 1 || !base || typeof r.id !== 'string'
    || !Array.isArray(r.evidence) || !Array.isArray(r.sources) || !r.preset?.morphology || !r.preset.colors
    || typeof r.title !== 'string' || typeof r.scientificName !== 'string' || typeof r.family !== 'string'
    || !Number.isSafeInteger(r.seed) || !Number.isInteger(r.revision) || r.revision < 1) throw new Error('지원하지 않는 레시피 형식입니다.');
  if (r.sources.length > 100 || r.evidence.length > 200) throw new Error('출처 또는 관찰값이 너무 많습니다.');
  const numeric = Object.entries(base.morphology).filter(([, v]) => typeof v === 'number').map(([k]) => k);
  if (numeric.some(k => !Number.isFinite((r.preset.morphology as unknown as Record<string, unknown>)[k]))) throw new Error('형태 파라미터에 유효하지 않은 숫자가 있습니다.');
  if (numeric.some(k => Math.abs((r.preset.morphology as unknown as Record<string, number>)[k]) > 10000)) throw new Error('형태 파라미터가 허용 범위를 초과했습니다.');
  if (Object.values(r.preset.colors).some(c => typeof c !== 'string' || !/^#[0-9a-f]{6}$/i.test(c))) throw new Error('색상은 6자리 HEX 형식이어야 합니다.');
  if (!['radial', 'sunflower', 'hydrangea', 'wisteria'].includes(r.preset.kind)
    || !['round', 'pointed', 'lance', 'notched', 'spoon'].includes(r.preset.morphology.petalShape)) throw new Error('지원하지 않는 형태입니다.');
  if (r.sources.some(s => typeof s.label !== 'string' || !/^https:\/\//.test(s.url))) throw new Error('출처 URL은 HTTPS 형식이어야 합니다.');
  if (r.evidence.some(e => !['petalLength','petalWidth','flowerDiameter','plantHeight'].includes(e.trait)
    || !['measured','reference','procedural'].includes(e.origin) || !['mm','cm'].includes(e.unit)
    || !Number.isFinite(e.value) || e.value <= 0 || !Number.isFinite(e.uncertainty) || e.uncertainty < 0
    || (e.origin !== 'procedural' && !/^https:\/\//.test(e.sourceUrl)))) throw new Error('관찰값의 단위·출처·숫자를 확인하세요.');
  const p = r.preset.pattern;
  if (!p || !['plain','veined','speckled','picotee','star'].includes(p.mode)
    || !/^#[0-9a-f]{6}$/i.test(p.color) || !['strength','veinFrequency','spotDensity','edgeStrength','centerStrength','seed'].every(k => Number.isFinite((p as unknown as Record<string, unknown>)[k]))) throw new Error('패턴 형식이 올바르지 않습니다.');
  const next = structuredClone(r);
  next.preset.id = base.id; // Keep organ algorithms linked to the template, separate from recipe identity.
  next.preset = sanitizePreset(next.preset);
  next.preset.pattern = { ...p, procedural: true, strength: Math.min(1, Math.max(0,p.strength)), veinFrequency: Math.min(20,Math.max(1,p.veinFrequency)), spotDensity: Math.min(1,Math.max(0,p.spotDensity)), edgeStrength: Math.min(1,Math.max(0,p.edgeStrength)), centerStrength: Math.min(1,Math.max(0,p.centerStrength)) };
  next.preset.morphology.stemHeight = Math.max(0.3, Math.min(6,next.preset.morphology.stemHeight));
  next.preset.morphology.flowerScale = Math.max(0.15, Math.min(4,next.preset.morphology.flowerScale));
  next.preset.morphology.sepalCount = Math.max(0, Math.min(24,Math.round(next.preset.morphology.sepalCount)));
  if (next.preset.architecture) {
    for (const key of ['floweringShootCount','branchCount','leafCount'] as const) {
      const n = next.preset.architecture[key];
      if (!Number.isFinite(n) || n < 0 || n > 24) throw new Error('기관 수는 0~24 범위여야 합니다.');
    }
  }
  return next;
}

export function parseLibrary(value: unknown): Recipe[] {
  const v = value as { schema?: string; recipes?: unknown[] };
  const entries = v?.schema === 'floraxis.library' ? v.recipes : [value];
  if (!Array.isArray(entries) || entries.length > 200) throw new Error('한 번에 200개 이하의 레시피를 가져올 수 있습니다.');
  const recipes = entries.map(parseRecipe);
  if (new Set(recipes.map(r => r.id)).size !== recipes.length) throw new Error('중복된 레시피 ID가 있습니다.');
  return recipes;
}
