import * as THREE from 'three';
import type { Recipe } from './recipe';

export interface MeshReport { meshes: number; vertices: number; triangles: number; invalidValues: number; degenerateTriangles: number; bounds: number[]; }

/** Freeze visible vertices (including morphs and instance transforms) at the selected growth stage. */
export function bakeSnapshot(root: THREE.Object3D): THREE.Group {
  root.updateMatrixWorld(true);
  const result = new THREE.Group();
  result.name = 'Floraxis static specimen';
  const matrix = new THREE.Matrix4(), point = new THREE.Vector3(), instanceColor = new THREE.Color();
  const materials = new Map<THREE.Material, THREE.MeshStandardMaterial>();
  const exportMaps = new Map<THREE.Texture,THREE.Texture>();
  const exportMap = (map: THREE.Texture | null, isColor = true) => {
    const image=map?.image as {data?: ArrayLike<number>;width:number;height:number}|undefined;
    if(!map || !image?.data) return map;
    const cached=exportMaps.get(map);if(cached)return cached;
    const {data,width,height}=image;
    const pixels=new Uint8ClampedArray(data);
    for(let i=0;i<pixels.length;i+=4)for(let channel=0;channel<3;channel++){
      const linear=pixels[i+channel]/255;
      if(isColor&&map.colorSpace!==THREE.SRGBColorSpace)pixels[i+channel]=Math.round((linear<=0.0031308?linear*12.92:1.055*linear**(1/2.4)-0.055)*255);
    }
    const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
    canvas.getContext('2d')!.putImageData(new ImageData(pixels,width,height),0,0);
    const result=new THREE.CanvasTexture(canvas);result.colorSpace=isColor?THREE.SRGBColorSpace:THREE.NoColorSpace;result.flipY=map.flipY;
    result.wrapS=map.wrapS;result.wrapT=map.wrapT;result.repeat.copy(map.repeat);result.offset.copy(map.offset);
    result.userData.exportOwned=true;exportMaps.set(map,result);return result;
  };
  const convert = (source: THREE.Material) => {
    let material = materials.get(source);
    if (!material) {
      const p = source as THREE.MeshStandardMaterial;
      material = new THREE.MeshStandardMaterial({ name: p.name || 'Floraxis PBR', color: p.color?.clone() ?? new THREE.Color('white'), roughness: p.roughness ?? 0.6,
        metalness: p.metalness ?? 0, vertexColors: p.vertexColors, side: p.side, map: exportMap(p.map), normalMap: exportMap(p.normalMap,false),
        transparent: p.transparent, opacity: p.opacity, alphaTest: p.alphaTest });
      material.normalScale.copy(p.normalScale ?? new THREE.Vector2(1,1));
      materials.set(source,material);
    }
    return material;
  };
  root.traverseVisible(object => {
    if (!(object as THREE.Mesh).isMesh) return;
    const mesh = object as THREE.Mesh;
    const instance = mesh as THREE.InstancedMesh;
    const count = instance.isInstancedMesh ? instance.count : 1;
    const proxy = new THREE.Mesh(mesh.geometry,mesh.material);
    for (let i = 0; i < count; i++) {
      if (instance.isInstancedMesh) {
        instance.getMatrixAt(i,matrix);
        matrix.premultiply(mesh.matrixWorld);
        if (instance.morphTexture) instance.getMorphAt(i,proxy);
        else proxy.morphTargetInfluences = mesh.morphTargetInfluences?.slice();
      } else {
        matrix.copy(mesh.matrixWorld);
        proxy.morphTargetInfluences = mesh.morphTargetInfluences?.slice();
      }
      if (Math.abs(matrix.determinant()) < 1e-15) continue;
      const geometry = mesh.geometry.clone();
      const position = geometry.getAttribute('position');
      for (let j=0;j<position.count;j++) {
        proxy.getVertexPosition(j,point).applyMatrix4(matrix);
        position.setXYZ(j,point.x,point.y,point.z);
      }
      geometry.morphAttributes = {};
      geometry.computeVertexNormals();
      let material = Array.isArray(mesh.material) ? mesh.material.map(convert) : convert(mesh.material);
      if (instance.isInstancedMesh && instance.instanceColor) {
        instance.getColorAt(i,instanceColor);
        const tint = (m: THREE.MeshStandardMaterial) => { const c=m.clone();c.color.multiply(instanceColor);return c; };
        material = Array.isArray(material) ? material.map(tint) : tint(material);
      }
      const usedMaterials=Array.isArray(material)?material:[material];
      if(usedMaterials.some(m=>m.normalMap)&&geometry.getAttribute('uv')) {
        if(!geometry.index)geometry.setIndex(Array.from({length:position.count},(_,i)=>i));
        geometry.computeTangents();
      } else if(!usedMaterials.some(m=>m.map)) {
        geometry.deleteAttribute('uv');
      }
      const baked = new THREE.Mesh(geometry,material);
      baked.name = `${mesh.name || 'organ'}-${result.children.length}`;
      result.add(baked);
    }
  });
  return result;
}

export function inspectMesh(root: THREE.Object3D): MeshReport {
  const report: MeshReport = { meshes:0, vertices:0, triangles:0, invalidValues:0, degenerateTriangles:0, bounds:[] };
  const a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3();
  root.traverse(object => {
    if (!(object as THREE.Mesh).isMesh) return;
    const geometry=(object as THREE.Mesh).geometry, p=geometry.getAttribute('position'), index=geometry.index;
    report.meshes++; report.vertices += p.count;
    const n=index?.count ?? p.count;
    report.triangles += Math.floor(n/3);
    for(let i=0;i<p.count;i++) if(!Number.isFinite(p.getX(i))||!Number.isFinite(p.getY(i))||!Number.isFinite(p.getZ(i))) report.invalidValues++;
    for(let i=0;i+2<n;i+=3) {
      a.fromBufferAttribute(p,index ? index.getX(i):i); b.fromBufferAttribute(p,index?index.getX(i+1):i+1); c.fromBufferAttribute(p,index?index.getX(i+2):i+2);
      if (b.sub(a).cross(c.sub(a)).lengthSq()<1e-20) report.degenerateTriangles++;
    }
  });
  const size=new THREE.Box3().setFromObject(root).getSize(new THREE.Vector3());
  report.bounds=[size.x,size.y,size.z];
  return report;
}

export function disposeSnapshot(root: THREE.Object3D): void {
  const materials=new Set<THREE.Material>();
  root.traverse(object=>{if((object as THREE.Mesh).isMesh){const m=object as THREE.Mesh;m.geometry.dispose();(Array.isArray(m.material)?m.material:[m.material]).forEach(v=>materials.add(v));}});
  const ownedTextures=new Set<THREE.Texture>();
  materials.forEach(m=>{for(const map of [(m as THREE.MeshStandardMaterial).map,(m as THREE.MeshStandardMaterial).normalMap]){if(map?.userData.exportOwned)ownedTextures.add(map);}m.dispose();});
  ownedTextures.forEach(map=>map.dispose());
}

export async function exportSpecimen(recipe: Recipe, bloom: number, download = true) {
  const { FloweringPlantModel } = await import('../flower/flowering-plant-model');
  const { GLTFExporter } = await import('three/addons/exporters/GLTFExporter.js');
  const model = new FloweringPlantModel(recipe.preset);
  let snapshot: THREE.Group | undefined;
  try {
    model.update(bloom,0);
    snapshot=bakeSnapshot(model.root);
    const report=inspectMesh(snapshot);
    if(report.invalidValues || !report.triangles) throw new Error('유효한 메시를 만들지 못했습니다. 형태 파라미터를 확인하세요.');
    snapshot.userData={ recipeId:recipe.id, revision:recipe.revision, bloom, units:'normalized display units; not a measurement scan', seed:recipe.seed, recipe, meshReport:report, materialNote:'TSL pattern baked to texture; SSS approximated with standard PBR' };
    const binary=await new GLTFExporter().parseAsync(snapshot,{binary:true, onlyVisible:true});
    if (!(binary instanceof ArrayBuffer)) throw new Error('GLB 생성 실패');
    if(download) downloadBlob(new Blob([binary],{type:'model/gltf-binary'}),`${safeName(recipe.title)}-bloom${Math.round(bloom*100)}.glb`);
    return {binary,report};
  } finally { if(snapshot) disposeSnapshot(snapshot);model.dispose(); }
}

export const safeName = (name: string): string => name.replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').slice(0,80) || 'floraxis';
export function downloadBlob(blob: Blob, filename: string) {
  const link=document.createElement('a'); const url=URL.createObjectURL(blob);
  link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);
}
export const downloadJSON = (value: unknown, filename: string) => downloadBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),filename);
